import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import {
  afterNextRender,
  computed,
  DestroyRef,
  inject,
  Injectable,
  PLATFORM_ID,
  signal,
} from '@angular/core';
import { MatSnackBar } from '@angular/material/snack-bar';
import { SupportConfigApiService } from '@pu-stats/data-access';
import { buyMeACoffeeUrl, type SupportConfig } from '@pu-stats/models';
import { createKeyedBusyState } from '@pu-stats/ui';

import { PlayBillingService, type TipProduct } from './play-billing.service';
import { isTwaSession } from './twa-session';

/**
 * What the support buttons offer: the Buy Me a Coffee page on the web, Play
 * tip products inside the Play Store app (Google Play only allows tips to
 * the developer through Play Billing), or nothing.
 *
 * Both come from the admin-maintained `appConfig/support` doc. Resolved
 * after the first render so the server HTML (which cannot know the
 * referrer) and the hydrated DOM agree.
 */
@Injectable({ providedIn: 'root' })
export class SupportLinkService {
  private readonly api = inject(SupportConfigApiService);
  private readonly billing = inject(PlayBillingService);
  private readonly snackBar = inject(MatSnackBar);
  private readonly document = inject(DOCUMENT);

  private readonly handle = signal('');
  private readonly web = signal(false);
  private readonly products = signal<readonly TipProduct[]>([]);
  private loadedProductIds = '';
  private pendingConsumed = false;

  /** Buy Me a Coffee page, or `null` outside the web or without a handle. */
  readonly url = computed(() => {
    const handle = this.handle();
    return this.web() && handle ? buyMeACoffeeUrl(handle) : null;
  });
  /** Play tip products; empty outside the Play Store app. */
  readonly tipProducts = this.products.asReadonly();
  readonly available = computed(
    () => this.url() !== null || this.products().length > 0
  );
  readonly tipBusy = createKeyedBusyState<string>();

  constructor() {
    if (!isPlatformBrowser(inject(PLATFORM_ID))) return;
    const destroyRef = inject(DestroyRef);
    afterNextRender(() => {
      const twa = isTwaSession(this.document);
      this.web.set(!twa);
      const sub = this.api.watchConfig().subscribe((config) => {
        if (twa) void this.loadProducts(config);
        else this.handle.set(config.buyMeACoffeeHandle);
      });
      destroyRef.onDestroy(() => sub.unsubscribe());
    });
  }

  async tip(productId: string): Promise<void> {
    try {
      const outcome = await this.tipBusy.run(productId, () =>
        this.billing.buy(productId)
      );
      if (outcome === 'purchased') {
        this.snackBar.open(
          $localize`:@@support.play.thanks:Danke für den Kaffee! ☕`,
          undefined,
          { duration: 4000 }
        );
      }
    } catch {
      this.snackBar.open(
        $localize`:@@support.play.failed:Der Kauf hat nicht geklappt. Bitte versuch es noch einmal.`,
        undefined,
        { duration: 5000 }
      );
    }
  }

  private async loadProducts(config: SupportConfig): Promise<void> {
    const ids = config.playTipProductIds;
    const key = ids.join(',');
    if (key === this.loadedProductIds) return;
    this.loadedProductIds = key;
    if (!key) {
      this.products.set([]);
      return;
    }
    if (!this.pendingConsumed) {
      this.pendingConsumed = true;
      void this.billing.consumePending(ids);
    }
    const products = await this.billing.loadProducts(ids);
    if (key !== this.loadedProductIds) return;
    // A failed load is retried on the next config emission.
    if (products === null) this.loadedProductIds = '';
    this.products.set(products ?? []);
  }
}
/** Admin-maintained support links, stored at `appConfig/support`. */
export interface SupportConfig {
  /** `buymeacoffee.com/<handle>`; empty hides every support link. */
  readonly buyMeACoffeeHandle: string;
  /**
   * Consumable Play products offered as tips inside the Play Store app,
   * in display order; empty hides tipping there.
   */
  readonly playTipProductIds: readonly string[];
}

export const SUPPORT_CONFIG_DOC_PATH = 'appConfig/support';

/** Mirrored by the `appConfig` rule in `firestore.rules`. */
export const BUY_ME_A_COFFEE_HANDLE_PATTERN = /^[A-Za-z0-9_.-]{0,50}$/;

/**
 * Play Console product ids: lowercase letters, digits, `_` and `.`, starting
 * with a letter or digit. Mirrored by the `appConfig` rule.
 */
export const PLAY_TIP_PRODUCT_ID_PATTERN = /^[a-z0-9][a-z0-9_.]{0,39}$/;

/** The rule checks list entries by index, so this bound is hard-coded there. */
export const PLAY_TIP_PRODUCTS_MAX = 5;

export const EMPTY_SUPPORT_CONFIG: SupportConfig = {
  buyMeACoffeeHandle: '',
  playTipProductIds: [],
};

export function parseSupportConfig(data: unknown): SupportConfig {
  const raw = (data ?? {}) as {
    buyMeACoffeeHandle?: unknown;
    playTipProductIds?: unknown;
  };
  const handle =
    typeof raw.buyMeACoffeeHandle === 'string' &&
    BUY_ME_A_COFFEE_HANDLE_PATTERN.test(raw.buyMeACoffeeHandle)
      ? raw.buyMeACoffeeHandle
      : '';
  const productIds = Array.isArray(raw.playTipProductIds)
    ? raw.playTipProductIds
        .filter(
          (id): id is string =>
            typeof id === 'string' && PLAY_TIP_PRODUCT_ID_PATTERN.test(id)
        )
        .slice(0, PLAY_TIP_PRODUCTS_MAX)
    : [];
  return { buyMeACoffeeHandle: handle, playTipProductIds: productIds };
}

/**
 * Parses the admin's comma- or space-separated product id list. Returns the
 * ids in order without duplicates, or `null` when one of them is invalid or
 * there are too many.
 */
export function normalizePlayTipProductIds(input: string): string[] | null {
  const ids = [
    ...new Set(
      input
        .split(/[\s,;]+/)
        .map((id) => id.trim())
        .filter(Boolean)
    ),
  ];
  if (ids.length > PLAY_TIP_PRODUCTS_MAX) return null;
  return ids.every((id) => PLAY_TIP_PRODUCT_ID_PATTERN.test(id)) ? ids : null;
}

/**
 * Accepts what an admin is likely to paste — the bare handle, `@handle` or
 * the full page URL — and returns the handle, `''` to clear it, or `null`
 * when the input cannot be a handle.
 */
export function normalizeBuyMeACoffeeHandle(input: string): string | null {
  const path = input
    .trim()
    .replace(/^(?:https?:\/\/)?(?:www\.)?buymeacoffee\.com\//i, '')
    .replace(/^@/, '');
  const end = path.search(/[/?#]/);
  const handle = end < 0 ? path : path.slice(0, end);
  return BUY_ME_A_COFFEE_HANDLE_PATTERN.test(handle) ? handle : null;
}

export function buyMeACoffeeUrl(handle: string): string {
  return `https://buymeacoffee.com/${encodeURIComponent(handle)}`;
}

