import { isRunningInTwa } from '../android-platform';

const TWA_SESSION_KEY = 'pu.twa';

/**
 * Whether this page runs inside the Play Store app. The TWA is recognised by
 * its launch referrer, which a reload inside the app loses — hence the
 * session flag.
 */
export function isTwaSession(document: Document): boolean {
  const storage = document.defaultView?.sessionStorage;
  if (isRunningInTwa(document.referrer ?? '')) {
    try {
      storage?.setItem(TWA_SESSION_KEY, '1');
    } catch {
      // Storage blocked; the referrer still covers this page load.
    }
    return true;
  }
  try {
    return storage?.getItem(TWA_SESSION_KEY) === '1';
  } catch {
    return false;
  }
}
