import { DOCUMENT } from '@angular/common';
import { computed, inject, Injectable, signal } from '@angular/core';
import { GAME_SUPPORT } from './game-support';

/** The slice of an IAB TCF v2.2 TCData object the consent is read from. */
export interface TcData {
  readonly eventStatus: 'tcloaded' | 'cmpuishown' | 'useractioncomplete';
  readonly gdprApplies?: boolean;
  readonly purpose?: { readonly consents?: Readonly<Record<number, boolean>> };
  readonly vendor?: { readonly consents?: Readonly<Record<number, boolean>> };
}

export type TcfApi = (
  command: 'addEventListener',
  version: 2,
  callback: (tcData: TcData, success: boolean) => void
) => void;

export type AdsWindow = Window & {
  adsbygoogle?: object[];
  __tcfapi?: TcfApi;
  googlefc?: {
    callbackQueue?: Record<string, () => void>[];
    showRevocationMessage?: () => void;
  };
};

export const AD_SCRIPT_ID = 'bacteria-game-ads';

/** IAB TCF vendor id of "Google Advertising Products". */
const GOOGLE_VENDOR_ID = 755;
/** TCF purposes: 1 store and access information on a device, 3 and 4 build and use an ad profile. */
const PURPOSE_STORAGE = 1;
const PURPOSE_AD_PROFILE = 3;
const PURPOSE_AD_SELECT = 4;

export const TCF_POLL_INTERVAL_MS = 200;
const TCF_POLL_MAX_TRIES = 150;

/**
 * The AdSense script and the consent it waits for. The script also brings
 * the consent banner (Google Privacy & Messaging, a TCF v2.2 CMP), so it
 * loads with the app; the ad slots stay empty until the player has made a
 * choice, and show non-personalised ads unless they agreed to more.
 */
@Injectable({ providedIn: 'root' })
export class GameAds {
  private readonly options = inject(GAME_SUPPORT)?.ads ?? null;
  private readonly document = inject(DOCUMENT);
  private readonly window = this.document.defaultView as AdsWindow | null;

  private readonly answered = signal(false);
  private readonly targeted = signal(false);

  /** The ad unit the screens show, null without ads. */
  public readonly ad = this.options?.slot ? this.options : null;
  /** True once the player has answered the consent banner, or does not need to. */
  public readonly consentAnswered = this.answered.asReadonly();
  /** Whether the ads may be personalised. */
  public readonly personalised = this.targeted.asReadonly();
  public readonly ready = computed(
    () => this.ad !== null && this.answered()
  );

  public start(): void {
    if (!this.ad || !this.window) return;
    if (!this.document.getElementById(AD_SCRIPT_ID)) {
      const script = this.document.createElement('script');
      script.id = AD_SCRIPT_ID;
      script.async = true;
      script.crossOrigin = 'anonymous';
      script.src = `https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${encodeURIComponent(this.ad.client)}`;
      this.document.head.appendChild(script);
    }
    // The script installs `__tcfapi` once it has loaded.
    if (this.listen()) return;
    let tries = 0;
    const poll = setInterval(() => {
      if (this.listen() || ++tries >= TCF_POLL_MAX_TRIES) clearInterval(poll);
    }, TCF_POLL_INTERVAL_MS);
  }

  /** Fills an `<ins class="adsbygoogle">` that is in the page. */
  public fill(): void {
    if (!this.window) return;
    (this.window.adsbygoogle ??= []).push({});
  }

  /**
   * Opens the consent banner again. The choice made before holds until the
   * player completes a new one.
   */
  public openConsentSettings(): void {
    if (!this.window) return;
    const googlefc = (this.window.googlefc ??= {});
    (googlefc.callbackQueue ??= []).push({
      CONSENT_DATA_READY: () => googlefc.showRevocationMessage?.(),
    });
  }

  private listen(): boolean {
    const tcfApi = this.window?.__tcfapi;
    if (typeof tcfApi !== 'function') return false;
    tcfApi('addEventListener', 2, (tcData, success) => {
      if (success) this.apply(tcData);
    });
    return true;
  }

  private apply(tcData: TcData): void {
    if (tcData.gdprApplies === false) {
      this.publish(true);
      return;
    }
    if (
      tcData.eventStatus !== 'tcloaded' &&
      tcData.eventStatus !== 'useractioncomplete'
    ) {
      return;
    }
    const purposes = tcData.purpose?.consents ?? {};
    const vendors = tcData.vendor?.consents ?? {};
    this.publish(
      purposes[PURPOSE_STORAGE] === true &&
        purposes[PURPOSE_AD_PROFILE] === true &&
        purposes[PURPOSE_AD_SELECT] === true &&
        vendors[GOOGLE_VENDOR_ID] === true
    );
  }

  private publish(personalised: boolean): void {
    this.targeted.set(personalised);
    this.answered.set(true);
  }
}

import {
  afterRenderEffect,
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  inject,
  viewChild,
} from '@angular/core';
import { GameAds } from './game-ads.service';

/**
 * A responsive AdSense display ad. Takes no room until the player has
 * answered the consent banner, and none at all without ads.
 */
@Component({
  selector: 'feat-lazy-bac-game-ad-slot',
  template: `
    @if (ads.ready() && ads.ad; as ad) {
      <span class="label" aria-hidden="true">Ad</span>
      <ins
        #slot
        class="adsbygoogle"
        style="display: block"
        data-ad-format="auto"
        data-full-width-responsive="true"
        [attr.data-ad-client]="ad.client"
        [attr.data-ad-slot]="ad.slot"
        [attr.data-npa]="ads.personalised() ? null : '1'"
      ></ins>
    }
  `,
  styles: `
    :host {
      display: block;
    }
    .label {
      display: block;
      margin-bottom: 4px;
      font-size: 0.75rem;
      color: var(--bw-faint, #5b6878);
    }
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AdSlotComponent {
  protected readonly ads = inject(GameAds);
  private readonly slot = viewChild<ElementRef<HTMLElement>>('slot');

  public constructor() {
    let filled: HTMLElement | null = null;
    afterRenderEffect(() => {
      const slot = this.slot()?.nativeElement ?? null;
      if (!slot || slot === filled) return;
      filled = slot;
      this.ads.fill();
    });
  }
}

const TWA_SESSION_KEY = 'bacteria-game.twa';

/**
 * Whether the game runs inside the Play Store app. The Trusted Web Activity
 * opens it with the referrer `android-app://<package>`; a reload inside the
 * app loses that, hence the flag in the session storage.
 */
export function isTwaSession(document: Document): boolean {
  const storage = document.defaultView?.sessionStorage;
  if (document.referrer.startsWith('android-app://')) {
    try {
      storage?.setItem(TWA_SESSION_KEY, '1');
    } catch {
      // Storage blocked: the referrer still covers this page load.
    }
    return true;
  }
  try {
    return storage?.getItem(TWA_SESSION_KEY) === '1';
  } catch {
    return false;
  }
}

import { DOCUMENT } from '@angular/common';
import { inject, Injectable } from '@angular/core';

export const PLAY_BILLING_METHOD = 'https://play.google.com/billing';

/** A tip product as the Play Store sells it in the player's country. */
export interface TipProduct {
  readonly id: string;
  readonly title: string;
  readonly price: string;
}

export type TipOutcome = 'purchased' | 'cancelled';

interface DigitalGoodsItem {
  readonly itemId: string;
  readonly title: string;
  readonly price: { readonly currency: string; readonly value: string };
}

interface DigitalGoodsPurchase {
  readonly itemId: string;
  readonly purchaseToken: string;
}

/** The part of the Digital Goods API the app's billing bridge answers. */
export interface DigitalGoodsService {
  getDetails(itemIds: string[]): Promise<DigitalGoodsItem[]>;
  listPurchases(): Promise<DigitalGoodsPurchase[]>;
  consume(purchaseToken: string): Promise<void>;
}

export type DigitalGoodsWindow = Window & {
  getDigitalGoodsService?: (method: string) => Promise<DigitalGoodsService>;
};

/**
 * Tips inside the Play Store app, sold as consumable Play products through
 * the Digital Goods API and Payment Request.
 *
 * A tip unlocks nothing, so no server checks the purchase: consuming it
 * acknowledges it (Play refunds a purchase nobody acknowledged after three
 * days) and makes the product buyable again.
 */
@Injectable({ providedIn: 'root' })
export class PlayBillingService {
  private readonly window = inject(DOCUMENT)
    .defaultView as DigitalGoodsWindow | null;
  private service: Promise<DigitalGoodsService | null> | null = null;

  /** The products in the given order, or null without Play Billing. */
  public async loadProducts(
    ids: readonly string[]
  ): Promise<TipProduct[] | null> {
    const service = await this.digitalGoods();
    if (!service) return null;
    try {
      const items = await service.getDetails([...ids]);
      const byId = new Map(items.map((item) => [item.itemId, item]));
      return ids.flatMap((id) => {
        const item = byId.get(id);
        return item
          ? [{ id, title: item.title, price: formatPrice(item.price) }]
          : [];
      });
    } catch {
      return null;
    }
  }

  public async buy(productId: string): Promise<TipOutcome> {
    const service = await this.digitalGoods();
    if (!service || typeof PaymentRequest === 'undefined') {
      throw new Error('Play Billing is not available');
    }
    const request = new PaymentRequest(
      [{ supportedMethods: PLAY_BILLING_METHOD, data: { sku: productId } }],
      { total: { label: 'Total', amount: { currency: 'EUR', value: '0' } } }
    );
    let response: PaymentResponse;
    try {
      response = await request.show();
    } catch (err) {
      if (err instanceof DOMException && err.name === 'AbortError') {
        return 'cancelled';
      }
      throw err;
    }
    const purchaseToken = (
      response.details as { purchaseToken?: unknown } | undefined
    )?.purchaseToken;
    // The player has paid by now, so a failed consume is no failure to
    // them: `consumePending` on the next start acknowledges the purchase,
    // well inside Play's three days.
    if (typeof purchaseToken === 'string' && purchaseToken) {
      await service.consume(purchaseToken).catch(() => undefined);
    }
    await response.complete('success').catch(() => undefined);
    return 'purchased';
  }

  /**
   * Consumes the tips an app closed too early left unconsumed, so Play
   * neither refunds them nor refuses to sell the same tip again. Other
   * products are left alone.
   */
  public async consumePending(tipProductIds: readonly string[]): Promise<void> {
    const service = await this.digitalGoods();
    if (!service) return;
    try {
      const purchases = await service.listPurchases();
      await Promise.allSettled(
        purchases
          .filter((purchase) => tipProductIds.includes(purchase.itemId))
          .map((purchase) => service.consume(purchase.purchaseToken))
      );
    } catch {
      // Tried again on the next start.
    }
  }

  private digitalGoods(): Promise<DigitalGoodsService | null> {
    const pending = (this.service ??= this.connect());
    // A failed connect - the app's bridge not bound yet - is tried again on
    // the next call rather than turning billing off for the session.
    void pending.then((service) => {
      if (!service && this.service === pending) this.service = null;
    });
    return pending;
  }

  private async connect(): Promise<DigitalGoodsService | null> {
    const connect = this.window?.getDigitalGoodsService;
    if (typeof connect !== 'function') return null;
    try {
      return await connect.call(this.window, PLAY_BILLING_METHOD);
    } catch {
      return null;
    }
  }
}

function formatPrice(price: DigitalGoodsItem['price']): string {
  try {
    return new Intl.NumberFormat(undefined, {
      style: 'currency',
      currency: price.currency,
    }).format(Number(price.value));
  } catch {
    return `${price.value} ${price.currency}`;
  }
}

import { DOCUMENT } from '@angular/common';
import {
  afterNextRender,
  computed,
  inject,
  Injectable,
  signal,
} from '@angular/core';
import { GAME_SUPPORT } from './game-support';
import { PlayBillingService, TipProduct } from './play-billing.service';
import { isTwaSession } from './twa-session';

/** What happened to the last tip, for a line under the tip buttons. */
export type TipNotice = 'thanks' | 'failed' | null;

export function buyMeACoffeeUrl(handle: string): string {
  return `https://buymeacoffee.com/${encodeURIComponent(handle)}`;
}

/**
 * How a player can pay for the game where they play it: the Buy Me a
 * Coffee page on the web, the Play tip products inside the Play Store app,
 * which allows tips only through Play Billing - or nothing, inside the
 * shell. Decided after the first render, when the referrer tells the app
 * from the web.
 */
@Injectable({ providedIn: 'root' })
export class GameSupport {
  private readonly options = inject(GAME_SUPPORT);
  private readonly billing = inject(PlayBillingService);
  private readonly document = inject(DOCUMENT);

  private readonly where = signal<'web' | 'app' | null>(null);
  private readonly products = signal<readonly TipProduct[]>([]);
  private readonly buying = signal<string | null>(null);
  private readonly lastTip = signal<TipNotice>(null);

  /** The Buy Me a Coffee page, null in the app or without a handle. */
  public readonly url = computed(() => {
    const handle = this.options?.buyMeACoffeeHandle;
    return this.where() === 'web' && handle ? buyMeACoffeeUrl(handle) : null;
  });
  /** The tips the Play Store sells, empty outside the app. */
  public readonly tipProducts = this.products.asReadonly();
  public readonly available = computed(
    () => this.url() !== null || this.products().length > 0
  );
  /** The tip whose purchase is open, null while none is. */
  public readonly busyTip = this.buying.asReadonly();
  public readonly tipNotice = this.lastTip.asReadonly();

  public constructor() {
    if (!this.options) return;
    afterNextRender(() => {
      const app = isTwaSession(this.document);
      this.where.set(app ? 'app' : 'web');
      if (app) void this.loadProducts();
    });
  }

  public async tip(productId: string): Promise<void> {
    if (this.buying()) return;
    this.buying.set(productId);
    this.lastTip.set(null);
    try {
      const outcome = await this.billing.buy(productId);
      if (outcome === 'purchased') this.lastTip.set('thanks');
    } catch {
      this.lastTip.set('failed');
    } finally {
      this.buying.set(null);
    }
  }

  private async loadProducts(): Promise<void> {
    const ids = this.options?.playTipProductIds ?? [];
    if (ids.length === 0) return;
    void this.billing.consumePending(ids);
    this.products.set((await this.billing.loadProducts(ids)) ?? []);
  }
}

