import { DOCUMENT } from '@angular/common';
import { computed, inject, Injectable, signal } from '@angular/core';
import { GAME_SUPPORT } from './game-support';

/** The slice of an IAB TCF v2.2 TCData object the game waits for. */
export interface TcData {
  readonly eventStatus: 'tcloaded' | 'cmpuishown' | 'useractioncomplete';
  readonly gdprApplies?: boolean;
}

export type TcfApi = (
  command: 'addEventListener',
  version: 2,
  callback: (tcData: TcData, success: boolean) => void
) => void;

export type AdsWindow = Window & {
  adsbygoogle?: object[];
  __tcfapi?: TcfApi;
  googlefc?: {
    callbackQueue?: Record<string, () => void>[];
    showRevocationMessage?: () => void;
  };
};

export const AD_SCRIPT_ID = 'bacteria-game-ads';

export const TCF_POLL_INTERVAL_MS = 200;
const TCF_POLL_MAX_TRIES = 150;

/**
 * The AdSense script and the consent it waits for. The script also brings
 * the consent banner (Google Privacy & Messaging, a TCF v2.2 CMP), so it
 * loads with the app; the ad slots stay empty until the player has made a
 * choice. Whether the ads may be personalised AdSense reads from that
 * choice itself.
 */
@Injectable({ providedIn: 'root' })
export class GameAds {
  private readonly options = inject(GAME_SUPPORT)?.ads ?? null;
  private readonly document = inject(DOCUMENT);
  private readonly window = this.document.defaultView as AdsWindow | null;

  private readonly answered = signal(false);
  private started = false;

  /** The ad unit the screens show, null without ads. */
  public readonly ad = this.options?.slot ? this.options : null;
  /**
   * True once the consent banner reported a choice, or that none is
   * needed - and with it, that the banner is there to open again.
   */
  public readonly consentAnswered = this.answered.asReadonly();
  public readonly ready = computed(() => this.ad !== null && this.answered());

  public start(): void {
    if (!this.ad || !this.window || this.started) return;
    this.started = true;
    if (!this.document.getElementById(AD_SCRIPT_ID)) {
      const script = this.document.createElement('script');
      script.id = AD_SCRIPT_ID;
      script.async = true;
      script.crossOrigin = 'anonymous';
      script.src = `https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${encodeURIComponent(this.ad.client)}`;
      this.document.head.appendChild(script);
    }
    // The script installs `__tcfapi` once it has loaded. Without it - an
    // ad blocker, no consent message set up - no ads are asked for.
    if (this.listen()) return;
    let tries = 0;
    const poll = setInterval(() => {
      if (this.listen() || ++tries >= TCF_POLL_MAX_TRIES) clearInterval(poll);
    }, TCF_POLL_INTERVAL_MS);
  }

  /** Fills an `<ins class="adsbygoogle">` that is in the page. */
  public fill(): void {
    if (!this.window) return;
    (this.window.adsbygoogle ??= []).push({});
  }

  /**
   * Opens the consent banner again. The choice made before holds until the
   * player completes a new one.
   */
  public openConsentSettings(): void {
    const window = this.window;
    if (!window) return;
    const googlefc = (window.googlefc ??= {});
    (googlefc.callbackQueue ??= []).push({
      CONSENT_DATA_READY: () => window.googlefc?.showRevocationMessage?.(),
    });
  }

  private listen(): boolean {
    const tcfApi = this.window?.__tcfapi;
    if (typeof tcfApi !== 'function') return false;
    tcfApi('addEventListener', 2, (tcData, success) => {
      if (
        success &&
        (tcData.gdprApplies === false ||
          tcData.eventStatus === 'tcloaded' ||
          tcData.eventStatus === 'useractioncomplete')
      ) {
        this.answered.set(true);
      }
    });
    return true;
  }
}

import { TestBed } from '@angular/core/testing';
import {
  AD_SCRIPT_ID,
  AdsWindow,
  GameAds,
  TcData,
  TCF_POLL_INTERVAL_MS,
} from './game-ads.service';
import { GAME_SUPPORT, GameSupportOptions } from './game-support';

const OPTIONS: GameSupportOptions = {
  buyMeACoffeeHandle: 'wolf',
  playTipProductIds: [],
  androidPackage: 'de.wolsok.bacteriawars',
  ads: { client: 'ca-pub-1', slot: '42' },
};

describe('GameAds', () => {
  const adsWindow = window as AdsWindow;
  let listeners: ((tcData: TcData, success: boolean) => void)[];

  function setUp(options: GameSupportOptions | null = OPTIONS): GameAds {
    TestBed.configureTestingModule({
      providers: [{ provide: GAME_SUPPORT, useValue: options }],
    });
    return TestBed.inject(GameAds);
  }

  function installCmp(): void {
    adsWindow.__tcfapi = (_command, _version, callback) => {
      listeners.push(callback);
    };
  }

  function report(tcData: TcData): void {
    for (const listener of listeners) listener(tcData, true);
  }

  beforeEach(() => {
    jest.useFakeTimers();
    listeners = [];
  });

  afterEach(() => {
    jest.clearAllTimers();
    jest.useRealTimers();
    document.getElementById(AD_SCRIPT_ID)?.remove();
    delete adsWindow.__tcfapi;
    delete adsWindow.adsbygoogle;
    delete adsWindow.googlefc;
  });

  it('loads the ad script and listens for the consent once', () => {
    installCmp();
    const ads = setUp();

    ads.start();
    ads.start();

    const scripts = document.querySelectorAll(`#${AD_SCRIPT_ID}`);
    expect(scripts).toHaveLength(1);
    expect((scripts[0] as HTMLScriptElement).src).toBe(
      'https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-1'
    );
    expect(listeners).toHaveLength(1);
  });

  it('loads nothing without an ad unit', () => {
    const ads = setUp({ ...OPTIONS, ads: { client: 'ca-pub-1', slot: '' } });

    ads.start();

    expect(document.getElementById(AD_SCRIPT_ID)).toBeNull();
    expect(ads.ad).toBeNull();
  });

  it('loads nothing without support options, as inside the shell', () => {
    const ads = setUp(null);

    ads.start();

    expect(document.getElementById(AD_SCRIPT_ID)).toBeNull();
  });

  it('waits for the player to answer the consent banner', () => {
    installCmp();
    const ads = setUp();
    ads.start();

    report({ eventStatus: 'cmpuishown' });
    expect(ads.ready()).toBe(false);
    expect(ads.consentAnswered()).toBe(false);

    report({ eventStatus: 'useractioncomplete' });
    expect(ads.ready()).toBe(true);
    expect(ads.consentAnswered()).toBe(true);
  });

  it('shows ads at once to a player who answered on an earlier visit', () => {
    installCmp();
    const ads = setUp();
    ads.start();

    report({ eventStatus: 'tcloaded' });

    expect(ads.ready()).toBe(true);
  });

  it('needs no answer where the GDPR does not apply', () => {
    installCmp();
    const ads = setUp();
    ads.start();

    report({ eventStatus: 'cmpuishown', gdprApplies: false });

    expect(ads.ready()).toBe(true);
  });

  it('listens once the script has brought the consent banner', () => {
    const ads = setUp();
    ads.start();
    expect(listeners).toHaveLength(0);

    installCmp();
    jest.advanceTimersByTime(TCF_POLL_INTERVAL_MS);
    jest.advanceTimersByTime(TCF_POLL_INTERVAL_MS * 5);

    expect(listeners).toHaveLength(1);
  });

  it('fills a slot by pushing to the ad queue', () => {
    const ads = setUp();

    ads.fill();

    expect(adsWindow.adsbygoogle).toEqual([{}]);
  });

  it('opens the consent banner again once the consent data is ready', () => {
    const ads = setUp();

    ads.openConsentSettings();
    // The consent script may set up its own object meanwhile.
    const queue = adsWindow.googlefc?.callbackQueue;
    const showRevocationMessage = jest.fn();
    adsWindow.googlefc = { callbackQueue: queue, showRevocationMessage };
    queue?.[0]?.['CONSENT_DATA_READY']?.();

    expect(showRevocationMessage).toHaveBeenCalled();
  });
});

