/** The faces of the menu screens: Bricolage Grotesque for display, Atkinson Hyperlegible for text. */
export const FONTS_URL =
  'https://fonts.googleapis.com/css2?family=Atkinson+Hyperlegible:wght@400;700&family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,800&display=swap';

/**
 * Links the game's fonts into the page, unless it has them already - an app
 * may link them in its index.html to have them for its loading screen. The
 * game loads them itself so a host app does not pay for them on every page.
 */
export function loadFonts(doc: Document): void {
  if (doc.querySelector(`link[href="${FONTS_URL}"]`) != null) {
    return;
  }
  const link = doc.createElement('link');
  link.rel = 'stylesheet';
  link.href = FONTS_URL;
  doc.head.append(link);
}
/** The longest wait between two tries. */
const MAX_DELAY_MS = 60_000;

/**
 * Waits before the next try of something that failed `attempt` times:
 * until the device is online again when it is not, else a while, twice as
 * long each time up to a minute.
 */
export function beforeRetry(attempt: number): Promise<void> {
  if (globalThis.navigator?.onLine === false) {
    return new Promise((resolve) =>
      window.addEventListener('online', () => resolve(), { once: true })
    );
  }
  const delay = Math.min(1000 * 2 ** attempt, MAX_DELAY_MS);
  return new Promise((resolve) => setTimeout(resolve, delay));
}

/** The code of a Firebase error, "" for anything else. */
export function errorCode(error: unknown): string {
  const code = (error as { code?: unknown } | null)?.code;
  return typeof code === 'string' ? code : '';
}
