/**
 * Creates or updates the Play tip products from `store/play/tips.json` and
 * activates their purchase option.
 *
 *   node tools/src/publish-play-tips.mjs            # dry run: prints the plan
 *   node tools/src/publish-play-tips.mjs --commit   # writes to Play
 *
 * Uses the one-time products API (`monetization.onetimeproducts`), which
 * is not edit-based: every product is its own upsert. Prices come from
 * `pricing:convertRegionPrices`, so each region gets Play's local price for
 * the tax-exclusive EUR base price in the source.
 *
 * Setup and prerequisites: docs/play-store-publishing.md#trinkgeld-produkte
 */

import { pathToFileURL } from 'node:url';

import {
  API_ROOT,
  authorizedFetch,
  buildAuth,
  PACKAGE_NAME,
} from './play-api.mjs';
import {
  buildOneTimeProduct,
  eurMoney,
  formatMoney,
  loadTips,
  PURCHASE_OPTION_ID,
  validateTips,
} from './play-tips-source.mjs';

/** Regions whose price the plan prints; all others are set too. */
const PREVIEW_REGIONS = ['DE', 'AT', 'CH', 'US', 'GB'];

export function createTipsApi(auth, packageName = PACKAGE_NAME) {
  const app = `${API_ROOT}/applications/${packageName}`;
  return {
    convertPrice: (basePriceEur) =>
      authorizedFetch(auth, `${app}/pricing:convertRegionPrices`, {
        method: 'POST',
        body: JSON.stringify({ price: eurMoney(basePriceEur) }),
      }),
    getProduct: async (productId) => {
      try {
        return await authorizedFetch(
          auth,
          `${app}/onetimeproducts/${productId}`
        );
      } catch (error) {
        if (error.status === 404) return null;
        throw error;
      }
    },
    upsertProduct: (product, regionsVersion) => {
      const query = new URLSearchParams({
        allowMissing: 'true',
        'regionsVersion.version': regionsVersion,
        updateMask: 'listings,purchaseOptions',
      });
      return authorizedFetch(
        auth,
        `${app}/onetimeproducts/${product.productId}?${query}`,
        { method: 'PATCH', body: JSON.stringify(product) }
      );
    },
    activatePurchaseOption: (productId) =>
      authorizedFetch(
        auth,
        `${app}/oneTimeProducts/${productId}/purchaseOptions:batchUpdateStates`,
        {
          method: 'POST',
          body: JSON.stringify({
            requests: [
              {
                activatePurchaseOptionRequest: {
                  packageName,
                  productId,
                  purchaseOptionId: PURCHASE_OPTION_ID,
                },
              },
            ],
          }),
        }
      ),
  };
}

export async function publishTips({
  tips,
  api,
  commit,
  packageName = PACKAGE_NAME,
  log = console.log,
}) {
  const errors = validateTips(tips);
  if (errors.length > 0) {
    throw new Error(`store/play/tips.json is invalid:\n${errors.join('\n')}`);
  }

  for (const tip of tips) {
    const converted = await api.convertPrice(tip.basePriceEur);
    const product = buildOneTimeProduct(tip, converted, packageName);
    const existing = await api.getProduct(tip.id);
    const prices = new Map(
      product.purchaseOptions[0].regionalPricingAndAvailabilityConfigs.map(
        (config) => [config.regionCode, config.price]
      )
    );
    log(
      `\n${tip.id} (${existing ? 'update' : 'new'}) – ` +
        `"${tip.listings['de-DE'].title}", base ${tip.basePriceEur} EUR net, ` +
        `${prices.size} regions`
    );
    for (const region of PREVIEW_REGIONS) {
      log(`  ${region}: ${formatMoney(prices.get(region))}`);
    }

    if (!commit) continue;
    const regionsVersion = converted.regionVersion?.version;
    if (!regionsVersion) {
      throw new Error(
        `${tip.id}: Play returned no regions version for the prices`
      );
    }
    await api.upsertProduct(product, regionsVersion);
    if (!isActive(existing)) await api.activatePurchaseOption(tip.id);
    log('  ✓ saved and purchase option active');
  }

  log(
    commit
      ? `\nPublished ${tips.length} tip product(s). Enter their ids in the admin area under "Unterstützung".`
      : `\nDry run: nothing was written. Re-run with --commit to publish.`
  );
}

function isActive(product) {
  return (
    product?.purchaseOptions?.find(
      (option) => option.purchaseOptionId === PURCHASE_OPTION_ID
    )?.state === 'ACTIVE'
  );
}

async function main() {
  const commit = process.argv.slice(2).includes('--commit');
  // Validation runs before any network call, so a bad source fails fast.
  const tips = loadTips();
  await publishTips({ tips, commit, api: createTipsApi(buildAuth()) });
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(process.argv[1]).href
) {
  main().catch((error) => {
    console.error(error.message);
    process.exitCode = 1;
  });
}
