import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  countCharacters,
  SUPPORTED_PLAY_LOCALES,
} from './play-listing-source.mjs';

/**
 * The tip products the Play Store app sells (issue #836), as consumable
 * one-time products. Their ids are what admins enter under "Unterstützung";
 * the app reads titles and prices back from Play at runtime.
 */
export const TIPS_FILE = resolve(
  dirname(fileURLToPath(import.meta.url)),
  '../..',
  'store/play/tips.json'
);

/** The one purchase option every tip has; tips are bought, never rented. */
export const PURCHASE_OPTION_ID = 'buy';

/** Play Console limits for one-time product listings. */
export const TIP_LIMITS = { title: 55, description: 200 };

/** Mirrors `PLAY_TIP_PRODUCT_ID_PATTERN` in `@pu-stats/models`. */
export const TIP_PRODUCT_ID_PATTERN = /^[a-z0-9][a-z0-9_.]{0,39}$/;

const PRICE_PATTERN = /^\d+\.\d{2}$/;

export function loadTips(file = TIPS_FILE) {
  return JSON.parse(readFileSync(file, 'utf8')).products;
}

/** Every problem in the source, so one run reports all of them. */
export function validateTips(tips) {
  const errors = [];
  const seen = new Set();
  for (const tip of tips) {
    const where = tip.id ?? '(no id)';
    if (!TIP_PRODUCT_ID_PATTERN.test(tip.id ?? '')) {
      errors.push(`${where}: invalid product id`);
    }
    if (seen.has(tip.id)) errors.push(`${where}: duplicate product id`);
    seen.add(tip.id);
    if (!PRICE_PATTERN.test(tip.basePriceEur ?? '')) {
      errors.push(`${where}: basePriceEur must look like "2.52"`);
    }
    const locales = Object.keys(tip.listings ?? {});
    for (const locale of SUPPORTED_PLAY_LOCALES) {
      if (!locales.includes(locale)) errors.push(`${where}: missing ${locale}`);
    }
    for (const locale of locales) {
      if (!SUPPORTED_PLAY_LOCALES.includes(locale)) {
        errors.push(`${where}: unsupported locale ${locale}`);
        continue;
      }
      for (const [field, max] of Object.entries(TIP_LIMITS)) {
        const text = tip.listings[locale][field] ?? '';
        const length = countCharacters(text);
        if (length === 0) errors.push(`${where} ${locale}: empty ${field}`);
        if (length > max) {
          errors.push(`${where} ${locale}: ${field} ${length}/${max}`);
        }
      }
    }
  }
  return errors;
}

/** `"2.52"` → Money for EUR. */
export function eurMoney(amount) {
  const [units, cents] = amount.split('.');
  return {
    currencyCode: 'EUR',
    units,
    nanos: Number(cents.padEnd(9, '0')),
  };
}

/**
 * The OneTimeProduct to upsert for `tip`, priced per region from a
 * `pricing:convertRegionPrices` response.
 */
export function buildOneTimeProduct(tip, converted, packageName) {
  const regional = Object.values(converted.convertedRegionPrices ?? {})
    .map((region) => ({
      regionCode: region.regionCode,
      price: region.price,
      availability: 'AVAILABLE',
    }))
    .sort((a, b) => a.regionCode.localeCompare(b.regionCode));
  const other = converted.convertedOtherRegionsPrice ?? {};
  return {
    packageName,
    productId: tip.id,
    listings: Object.entries(tip.listings).map(([languageCode, text]) => ({
      languageCode,
      title: text.title,
      description: text.description,
    })),
    purchaseOptions: [
      {
        purchaseOptionId: PURCHASE_OPTION_ID,
        // The TWA billing bridge predates the one-time-products model.
        buyOption: { legacyCompatible: true, multiQuantityEnabled: false },
        regionalPricingAndAvailabilityConfigs: regional,
        newRegionsConfig: {
          availability: 'AVAILABLE',
          eurPrice: other.eurPrice,
          usdPrice: other.usdPrice,
        },
      },
    ],
  };
}

